mapper.select:

left join system_common_group as commonGroup on appCommonGroup.common_group_id = commonGroup.id

    appCommonGroup.deleted_flag = 'N'
    and appCommonGroup.app_id = #{appId}
    and appCommonGroup.common_group_id =
        #{commonGroupId}

    and appCommonGroup.status = #{status}
    and appCommonGroup.remark like concat('%', #{remark}, '%')
    and appCommonGroup.organization_id =
        #{organizationId}


        and

            (
            appCommonGroup.remark like concat('%', #{item}, '%')
            )



order by appCommonGroup.created_time desc
